// Base64-encoded Outfit TTF fonts for deterministic runtime-agnostic rendering in ImageResponse
export const OUTFIT_REGULAR_BASE64 = '';
export const OUTFIT_BOLD_BASE64 = '';
export const OUTFIT_BLACK_BASE64 = '';

export function getOutfitFonts() {
  const buf400 = Buffer.from(OUTFIT_REGULAR_BASE64, 'base64');
  const buf700 = Buffer.from(OUTFIT_BOLD_BASE64, 'base64');
  const buf900 = Buffer.from(OUTFIT_BLACK_BASE64, 'base64');

  return [
    {
      name: 'Outfit',
      data: buf400.buffer.slice(buf400.byteOffset, buf400.byteOffset + buf400.byteLength),
      weight: 400 as const,
      style: 'normal' as const,
    },
    {
      name: 'Outfit',
      data: buf700.buffer.slice(buf700.byteOffset, buf700.byteOffset + buf700.byteLength),
      weight: 700 as const,
      style: 'normal' as const,
    },
    {
      name: 'Outfit',
      data: buf900.buffer.slice(buf900.byteOffset, buf900.byteOffset + buf900.byteLength),
      weight: 900 as const,
      style: 'normal' as const,
    },
  ];
}
